import pickle
with open("/tmp/samples.pkl","rb") as f:
    samples=pickle.load(f)

def to_grid_padded(s, width=80):
    lines = s.split("\n")
    grids=[]
    for line in lines:
        cols=[]; bg=False; i=0
        while i < len(line):
            if line[i]=="\x1b" and i+1<len(line) and line[i+1]=="[":
                j=line.find("m", i)
                if j!=-1:
                    seq=line[i:j+1]
                    for c in range(8):
                        if f"4{c}m" in seq: bg=True
                    if "49m" in seq: bg=False
                    i=j+1
                    continue
            elif line[i]=="\x0e" or line[i]=="\x0f":
                i+=1
                if i < len(line):
                    cols.append(line[i]); i+=1
                continue
            else:
                ch=line[i]
                if ch==" ": cols.append("#" if bg else ".")
                else: cols.append(ch)
                i+=1
        # pad with dots to width (since tmux trims trailing spaces)
        # But need to know if trailing spaces were bg or normal? Trailing normal spaces trimmed -> dots. Trailing bg spaces? Would they be trimmed? Probably not, since bg spaces are visible? Actually tmux trims trailing spaces regardless? For digits ending with # on rightmost column, trailing? Let's see: digits rightmost column for some digits is # (e.g., 0 rightmost #), for others like 1 rightmost # as well? Actually all digits rightmost column is #? Check fonts: For 1, rightmost is # (since 1 is `  ` at right). So trailing after last digit is normal spaces (dots) which are trimmed. So padding with dots is correct.
        while len(cols) < width:
            cols.append(".")
        grids.append("".join(cols[:width]))
    return grids

# re-parse with padding using raw e strings
# samples store e,p,grids where grids already parsed without padding. Need to re-parse e.
# samples[i][0] is e
