    e=dict(os.environ); e["TERM"]="xterm"
    try:
        p=subprocess.run(["./executable"]+args, capture_output=True, env=e, timeout=1)
        print(f"ARGS={args} rc={p.returncode} out={p.stdout[:200]!r} err={p.stderr[:500]!r}")
    except subprocess.TimeoutExpired as ex:
        print(f"ARGS={args} TIMEOUT out_len={len(ex.stdout or b'')}")

for a in [["-T","/nonexistent"], ["-T","/tmp"], ["-T","/dev/tty"], ["-T","/dev/zero"]]:
    run(a)
